Lemma fz_big1 : forall (fr : bvmap 5 word) cs regs (m : word -> option byte) (s sz dp : Z),
  frm_zero cs ->
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (3 <= sz < 2 ^ 64)%Z ->
  (0 <= dp < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
  getr regs 2 = Z_to_bv 64 s ->
  getr regs 10 = Z_to_bv 64 dp ->
  getr regs 11 = Z_to_bv 64 sz ->
  reach SEGS (@mkst (mkFP fr cs) regs (Z_to_bv 64 97544) m rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (Z_to_bv 64 98064) M' rom /\ frm_zero cs' /\
      rinv [((s - 64)%Z, 64%Z)] m M' /\
      rdn SEGS M' (Z_to_bv 64 (s - 8)) 8 = Some (word_to_le_bytes 8 (getr regs 1)) /\ rdn SEGS M' (Z_to_bv 64 (s - 16)) 8 = Some (word_to_le_bytes 8 (getr regs 8)) /\
      rdn SEGS M' (Z_to_bv 64 (s - 24)) 8 = Some (word_to_le_bytes 8 (getr regs 9)) /\ rdn SEGS M' (Z_to_bv 64 (s - 32)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (bv_unsigned (reg_get fr 8)))) /\
      getr regs' 1 = Z_to_bv 64 97592 /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 10 = Z_to_bv 64 97776 /\ getr regs' 8 = Z_to_bv 64 sz /\ getr regs' 9 = Z_to_bv 64 dp /\
      regs_agree (fun r => In r [1; 2; 8; 9; 10; 11]%list) regs regs' /\
      (forall r : reg, ~ In (ridx r) (@nil nat) -> reg_get fr' r = reg_get fr r)).
