Lemma fz_B0a : forall (fx : FPState) regs (m : word -> option byte) (s : Z),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  getr regs 10 = Z_to_bv 64 0 ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 97604) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 97748) M' rom /\
      rinv [((s - 40)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 40)) 8 = Some (Z_to_le_bytes 8 0) /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ regs_agree (fun r => In r (@nil (bv 5))) regs regs').
