Lemma fz_B1 : forall (fx : FPState) regs (m : word -> option byte) (s pixs : Z),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (1 <= pixs < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  getr regs 10 = Z_to_bv 64 pixs ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 97604) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 107284) M' rom /\
      rinv [((s - 40)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 40)) 8 = Some (Z_to_le_bytes 8 pixs) /\
      getr regs' 1 = Z_to_bv 64 97628 /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 8 = Z_to_bv 64 pixs /\ getr regs' 10 = Z_to_bv 64 0 /\ getr regs' 11 = Z_to_bv 64 pixs /\
